=== file: main.loom ===
budget { tokens: 20000  calls: 15 }

tool WebSearch { use: duckduckgo }

agent Researcher {
    model: "gpt-6-luna"
    prompt: "researcher"
    tools: [WebSearch]
    temperature: 0.2
    output_schema: { brief: string, sources: list<string> }
}

agent Critic {
    model: "gpt-6-luna"
    prompt: "critic"
    temperature: 0.2
    output_schema: { material_weaknesses: enum["YES", "NO"], feedback: string }
}

agent Reviser {
    model: "gpt-6-luna"
    prompt: "reviser"
    temperature: 0.2
    output_schema: { brief: string }
}

workflow Main(research_subject) {
    set chosen_subject = research_subject

    alt (research_subject == "") {
        human_prompt "What topic would you like researched?" -> replacement_subject
        alt (replacement_subject == "") {
            halt "No topic was provided; no research or approval was performed."
        } else {
            set chosen_subject = replacement_subject
        }
    }

    delegate "Research this topic using public web sources and prepare a brief with source references:\n{chosen_subject}" to Researcher -> search_packet expecting {
        brief: string,
        sources: list<string>
    } retry 2 backoff 2s timeout 60s on_failure {
        halt "Research failed after two retries; no unsupported brief was presented."
    }

    delegate "Check this sourced brief for factual accuracy, reasoning, coverage, balance, and source weaknesses. Topic:\n{chosen_subject}\n\nBrief:\n{search_packet.brief}\n\nSources:\n{search_packet.sources}" to Critic -> critique_notes expecting {
        material_weaknesses: enum["YES", "NO"],
        feedback: string
    } timeout 60s on_failure {
        halt "The critic failed; no approved brief was produced."
    }

    delegate "Revise this brief using the critic's feedback. Keep the result at or below 500 words, preserve supported claims and source references, and do not introduce unsupported claims. If the critic found no material weaknesses, preserve the brief without inventing changes.\n\nTopic:\n{chosen_subject}\n\nCritic found material weaknesses: {critique_notes.material_weaknesses}\nFeedback:\n{critique_notes.feedback}\n\nBrief:\n{search_packet.brief}\n\nSource references:\n{search_packet.sources}" to Reviser -> updated_brief expecting {
        brief: string
    } timeout 60s on_failure {
        halt "The reviser failed; no approved brief was produced."
    }

    human_prompt "Review the revised brief below. Reply with JSON containing decision (approve or reject) and requested_changes (a string). Only an explicit approve decision approves the brief.\n\nBrief:\n{updated_brief.brief}" -> approval_record expecting {
        decision: enum["approve", "reject"],
        requested_changes: string
    }

    alt (approval_record.decision == "approve") {
        return "APPROVED\n{updated_brief.brief}"
    } else {
        loop until (approval_record.decision == "approve") max 2 budget 8000 tokens {
            delegate "Address the approver's requested changes while preserving supported claims and source references. Keep the brief at or below 500 words. Do not describe it as approved.\n\nRequested changes:\n{approval_record.requested_changes}\n\nCurrent brief:\n{updated_brief.brief}" to Reviser -> updated_brief expecting {
                brief: string
            } timeout 60s on_failure {
                halt "The reviser failed; no approved brief was produced."
            }

            human_prompt "Review this revised brief. Reply with JSON containing decision (approve or reject) and requested_changes (a string). Only an explicit approve decision approves the brief.\n\nBrief:\n{updated_brief.brief}" -> approval_response expecting {
                decision: enum["approve", "reject"],
                requested_changes: string
            }
            set approval_record = approval_response
        } on_exhausted {
            alt (_loopExhaustedBy == "budget") {
                halt "The revision budget was exhausted; no approved brief was produced."
            } else {
                return "NOT APPROVED\n{updated_brief.brief}"
            }
        }

        return "APPROVED\n{updated_brief.brief}"
    }
}
